/* Library expansion. One row per exercise:
   [name, grp, eq ('' = none, '+' joins), diff 1–3, pattern, pri (display),
    primaryMuscleId, sec (display), setup, cues, opts]
   opts: { bw, j: {joint: 0–3}, met, src, style, mistakes, breathing }
   build-regressions.mjs fills joints / MET / steps / alternatives and skips
   anything that already exists in the DB. */
const R = (n, grp, eq, diff, pattern, pri, prim, sec, setup, cues, opts) =>
  ({ n, grp, eq, diff, pattern, pri, prim, sec, setup, cues, opts: opts || {} });

/* Shorthands for the long tail. */
const SPORT_SRC = 'CPA 2011 sports / recreation category (estimate)';
const SP = (n, met, setup, cues, o) => R(n, 'sports', '', (o && o.diff) || 1, 'conditioning', 'Full Body', 'full_body', 'Cardio', setup, cues, Object.assign({ met, src: SPORT_SRC }, o || {}));
const CARDIO = (n, met, setup, cues, o) => R(n, 'cardio', (o && o.eq) || '', (o && o.diff) || 1, 'conditioning', 'Cardio', 'cardio', 'Legs', setup, cues, Object.assign({ bw: true, met, src: 'CPA 2011 conditioning / locomotion category (estimate)' }, o || {}));
const PLYO = (n, diff, pri, prim, setup, cues, o) => R(n, 'plyometrics', (o && o.eq) || '', diff, 'conditioning', pri, prim, 'Calves, Glutes', setup, cues, Object.assign({ bw: true }, o || {}));
const DRILL = (n, diff, setup, cues, o) => R(n, 'warmup_drills', '', diff, 'conditioning', 'Legs', 'quads', 'Calves, Hip Flexors', setup, cues, Object.assign({ met: 8, src: 'CPA 2011 02020 calisthenics, vigorous (category estimate)' }, o || {}));
const STRETCH = (n, pri, prim, setup, cues, o) => R(n, 'mobility', (o && o.eq) || '', 1, 'isolation', pri, prim, '', setup, cues, Object.assign({ bw: true, style: 'stretch' }, o || {}));
const YOGA = (n, diff, pri, prim, setup, cues, o) => R(n, 'mobility', '', diff, 'isolation', pri, prim, '', setup, cues, Object.assign({ bw: true, style: 'yoga' }, o || {}));
const PILATES = (n, diff, setup, cues, o) => R(n, 'core', '', diff, 'core', 'Abs', 'abs', 'Hip Flexors, Lower Back', setup, cues, Object.assign({ bw: true, style: 'pilates' }, o || {}));
const REHAB = (n, grp, eq, pri, prim, setup, cues, o) => R(n, grp, eq, 1, (o && o.pattern) || 'isolation', pri, prim, '', setup, cues, Object.assign({ bw: !eq, style: 'rehab' }, o || {}));

